  modelica: {
    defaultCode:
      'model ThermalTank "First-order lumped-capacitance heated liquid tank"\n  parameter Real C(unit="J/K") = 41840.0 "Thermal capacitance of 10 kg water";\n  parameter Real R(unit="K/W") = 0.08 "Thermal resistance to ambient";\n  parameter Real T_amb(unit="K") = 293.15 "Ambient temperature (20 degC)";\n  parameter Real Q_heater(unit="W") = 1200.0 "Electric immersion heater power";\n  parameter Real T0(unit="K") = 293.15 "Initial tank temperature";\n\n  Real T(unit="K", start=T0, fixed=true) "Bulk liquid temperature";\n  Real Q_loss(unit="W") "Convective heat loss to environment";\n  Real T_degC(unit="degC") "Tank temperature in Celsius";\n\nequation\n  Q_loss = (T - T_amb) / R;\n  C * der(T) = Q_heater - Q_loss;\n  T_degC = T - 273.15;\n\n  annotation(\n    experiment(StartTime=0, StopTime=6000, Tolerance=1e-6),\n    Documentation(info="<html><p>First-order thermal tank model with steady-state temperature T_ss = T_amb + R*Q_heater.</p></html>")\n  );\nend ThermalTank;\n',
  },
  modelscript: {
    defaultCode:
      "struct BeamSection {\n  width: f64;\n  height: f64;\n  length: f64;\n  elasticModulus: f64;\n  yieldStrength: f64;\n}\n\nfunction secondMomentOfArea(sec: BeamSection): f64 {\n  return (sec.width * sec.height * sec.height * sec.height) / 12.0;\n}\n\nfunction maxBendingStress(sec: BeamSection, tipLoad: f64): f64 {\n  let moment: f64 = tipLoad * sec.length;\n  let inertia: f64 = secondMomentOfArea(sec);\n  let halfHeight: f64 = sec.height * 0.5;\n  return (moment * halfHeight) / inertia;\n}\n\nfunction tipDeflection(sec: BeamSection, tipLoad: f64): f64 {\n  let inertia: f64 = secondMomentOfArea(sec);\n  return (tipLoad * sec.length * sec.length * sec.length) / (3.0 * sec.elasticModulus * inertia);\n}\n\nfunction safetyFactor(sec: BeamSection, tipLoad: f64): f64 {\n  let sigmaMax: f64 = maxBendingStress(sec, tipLoad);\n  return sec.yieldStrength / sigmaMax;\n}\n",
  },
