  sdl: {
    defaultCode:
      "/* CCITT SDL-88 Ping-Pong Request-Response Protocol */\nSYSTEM PingPongProtocol;\n  SIGNAL Ping, Pong;\n  CHANNEL C_Link\n    FROM ClientBlock TO ServerBlock WITH Ping;\n    FROM ServerBlock TO ClientBlock WITH Pong;\n  ENDCHANNEL C_Link;\n\n  BLOCK ClientBlock;\n    SIGNALROUTE SR_Client\n      FROM Client TO ENV WITH Ping;\n      FROM ENV TO Client WITH Pong;\n    CONNECT C_Link AND SR_Client;\n\n    PROCESS Client(1, 1);\n      TIMER T_Retry;\n      START;\n        OUTPUT Ping VIA SR_Client;\n        SET(NOW + 2.0, T_Retry);\n        NEXTSTATE WaitPong;\n      STATE WaitPong;\n        INPUT Pong;\n          RESET(T_Retry);\n          OUTPUT Ping VIA SR_Client;\n          SET(NOW + 2.0, T_Retry);\n          NEXTSTATE WaitPong;\n        INPUT T_Retry;\n          OUTPUT Ping VIA SR_Client;\n          SET(NOW + 2.0, T_Retry);\n          NEXTSTATE WaitPong;\n      ENDSTATE WaitPong;\n    ENDPROCESS Client;\n  ENDBLOCK ClientBlock;\n\n  BLOCK ServerBlock;\n    SIGNALROUTE SR_Server\n      FROM ENV TO Server WITH Ping;\n      FROM Server TO ENV WITH Pong;\n    CONNECT C_Link AND SR_Server;\n\n    PROCESS Server(1, 1);\n      START;\n        NEXTSTATE Ready;\n      STATE Ready;\n        INPUT Ping;\n          OUTPUT Pong VIA SR_Server;\n          NEXTSTATE Ready;\n      ENDSTATE Ready;\n    ENDPROCESS Server;\n  ENDBLOCK ServerBlock;\nENDSYSTEM PingPongProtocol;\n",
  },
