  simscript: {
    defaultCode:
      "'' MODEL: SingleServerQueue\nPREAMBLE\n  TEMPORARY ENTITIES\n    EVERY CUSTOMER BELONGS TO WAIT.LINE\n  PROCESSES\n    INCLUDE ARRIVAL.GEN\n    INCLUDE CUSTOMER\n  RESOURCES\n    EVERY CLERK\n  DEFINE WAIT.LINE AS A FIFO SET\n  ACCUMULATE AVG.BUSY AS THE MEAN OF N.X.CLERK\n  ACCUMULATE AVG.QUEUE AS THE MEAN OF N.Q.CLERK\nEND\n\nMAIN\n  CREATE EVERY CLERK(1)\n  LET U.CLERK = 1\n  ACTIVATE AN ARRIVAL.GEN NOW\n  START SIMULATION\nEND\n\nPROCESS ARRIVAL.GEN\n  ACTIVATE A CUSTOMER NOW\n  ACTIVATE AN ARRIVAL.GEN IN EXPONENTIAL.F(5.0, 1) MINUTES\nEND\n\nPROCESS CUSTOMER\n  FILE THIS CUSTOMER IN WAIT.LINE\n  REQUEST 1 CLERK\n  REMOVE FIRST CUSTOMER FROM WAIT.LINE\n  WORK EXPONENTIAL.F(4.0, 2) MINUTES\n  RELINQUISH 1 CLERK\n  DESTROY THIS CUSTOMER\nEND\n",
  },
