      '`include "disciplines.vams"\n\nmodule temp_resistor(p, n);\n  inout p, n;\n  electrical p, n;\n\n  parameter real R0 = 1000.0 from (0:inf);\n  parameter real TC1 = 0.0039;\n  parameter real TC2 = 1.0e-6;\n  parameter real Tnom = 300.15 from (0:inf);\n\n  real dT, Reff;\n\n  analog begin\n    dT = $temperature - Tnom;\n    Reff = R0 * (1.0 + TC1 * dT + TC2 * dT * dT);\n    V(p, n) <+ I(p, n) * Reff;\n  end\nendmodule\n',
